from torch.utils.cpp_extension import load_inline

# CUDA kernel for matrix multiplication with warp-level parallelism
cuda_kernel_source = """
#include <torch/extension.h>

#define TILE_SIZE 32
#define WARPS_PER_BLOCK 4
#define THREADS_PER_WARP 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Each warp computes one output tile
    __shared__ float As[WARPS_PER_BLOCK][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[WARPS_PER_BLOCK][TILE_SIZE][TILE_SIZE];

    int warp_id = threadIdx.x / THREADS_PER_WARP;
    int lane_id = threadIdx.x % THREADS_PER_WARP;

    int warp_row = warp_id / (blockDim.x / THREADS_PER_WARP);
    int warp_col = warp_id % (blockDim.x / THREADS_PER_WARP);

    int row = blockIdx.y * TILE_SIZE * WARPS_PER_BLOCK + warp_row * TILE_SIZE;
    int col = blockIdx.x * TILE_SIZE * WARPS_PER_BLOCK + warp_col * TILE_SIZE;

    float sum[TILE_SIZE][TILE_SIZE] = {{0.0f}};

    for (int k = 0; k < N; k += TILE_SIZE) {
        // Load tile from A
        #pragma unroll
        for (int i = 0; i < TILE_SIZE; i += THREADS_PER_WARP) {
            int load_row = row + lane_id / (TILE_SIZE / 8);
            int load_col = k + (lane_id % (TILE_SIZE / 8)) * 8;

            if (load_row < N && load_col < N) {
                // Vectorized load: 8 elements at once
                float4 vec = reinterpret_cast<const float4*>(A + load_row * N + load_col)[0];
                As[warp_id][lane_id / (TILE_SIZE / 8)][(lane_id % (TILE_SIZE / 8)) * 8 + 0] = vec.x;
                As[warp_id][lane_id / (TILE_SIZE / 8)][(lane_id % (TILE_SIZE / 8)) * 8 + 1] = vec.y;
                As[warp_id][lane_id / (TILE_SIZE / 8)][(lane_id % (TILE_SIZE / 8)) * 8 + 2] = vec.z;
                As[warp_id][lane_id / (TILE_SIZE / 8)][(lane_id % (TILE_SIZE / 8)) * 8 + 3] = vec.w;
            }
        }

        // Load tile from B
        #pragma unroll
        for (int i = 0; i < TILE_SIZE; i += THREADS_PER_WARP) {
            int load_row = k + lane_id / (TILE_SIZE / 8);
            int load_col = col + (lane_id % (TILE_SIZE / 8)) * 8;

            if (load_row < N && load_col < N) {
