                float4 vec = reinterpret_cast<const float4*>(B + load_row * N + load_col)[0];
                Bs[warp_id][lane_id / (TILE_SIZE / 8)][(lane_id % (TILE_SIZE / 8)) * 8 + 0] = vec.x;
                Bs[warp_id][lane_id / (TILE_SIZE / 8)][(lane_id % (TILE_SIZE / 8)) * 8 + 1] = vec.y;
                Bs[warp_id][lane_id / (TILE_SIZE / 8)][(lane_id % (TILE_SIZE / 8)) * 8 + 2] = vec.z;
                Bs[warp_id][lane_id / (TILE_SIZE / 8)][(lane_id % (TILE_SIZE / 8)) * 8 + 3] = vec.w;
            }
